try:
    result = sc.gegenbauer(0, 0)
    probe("gegenbauer(0, 0)", result.c)
except Exception as e:
    probe("gegenbauer(0, 0)", "__error__: " + type(e).__name__ + ": " + str(e))

# Test gegenbauer(0, 1)
try:
    result = sc.gegenbauer(0, 1)
    probe("gegenbauer(0, 1)", result.c)
except Exception as e:
    probe("gegenbauer(0, 1)", "__error__: " + type(e).__name__ + ": " + str(e))

# Record expected values
try:
    probe("expected::gegenbauer(0, 0)", np.asarray([1.]))
except Exception as e:
    probe("expected::gegenbauer(0, 0)", "__error__: " + type(e).__name__ + ": " + str(e))

